{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Schisandrol B, the closest analogue (Morgan 0.7447) sharing the dibenzocyclooctadiene lignan core and tertiary alcohol, was detected in rat brain after oral administration, directly demonstrating BBB penetration for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Schisandrin B, a close scaffold analogue, had a logPSFu,brain of -3.2 and was classified as permeable, indicating rapid brain/plasma equilibration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Schisandrin B reached a brain tissue concentration of 0.327 µg/g in mice after administration, confirming meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Isocorydine, a related polymethoxylated aporphine, effectively crossed the BBB in rats with considerable brain levels within 10 minutes of administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine, a related polymethoxylated aporphine, reached brain concentrations nearly equal to plasma in rats, showing that this chemotype can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "N-nuciferine rapidly crossed the BBB in rat brain microdialysis with an unbound brain Cmax of 0.16 µg/mL after IV dosing, providing quantitative CNS exposure evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "(-)-Stepholidine, a related tetrahydroprotoberberine, showed good brain penetration with a brain:plasma AUC ratio of ~0.7 in rats.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tetrahydropalmatine was detected in rat CSF, confirming passage across the BBB for a related polymethoxylated alkaloid.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query is a polymethoxylated dibenzocyclooctadiene lignan closely related to Schisandrol B and Schisandrin B, both of which show direct brain penetration in rodents; multiple related polymethoxylated natural products also cross the BBB, so meaningful CNS access is expected.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or unbound brain concentration measurement for the exact query molecule.",
    "Most evidence is qualitative tissue detection or from close analogues rather than the query itself.",
    "Efflux transporter involvement was not directly assessed for the query.",
    "Human CNS exposure data are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

